/* D118 会话空间；只读核心事实，交互仅保存于本页内存。 */
const chState={id:'billing',pane:'middle',right:true,thread:null,preview:'normal',actor:'sam',search:'',drafts:{},messages:{},replies:{},dispatch:null,decision:null,permission:null,deadline:0};
const chRooms=[
 {id:'mentions',name:'提及与线程',project:'p1',topic:'与你有关的提及与回复',members:['sam','morgan','chen','ada','cy','lead','iris'],unread:4},
 {id:'billing',name:'# 账单中心',project:'p1',topic:'CSV 导出、税额修复与交付协作',members:['sam','morgan','chen','ada','bo','cy','lead','iris','echo'],unread:3,mention:true},
 {id:'billing-review',name:'# 账单中心-评审',project:'p1',topic:'证据、内部验收与团队裁决',members:['sam','morgan','chen','ada','cy'],unread:2},
 {id:'docs',name:'# 文档站',project:'p3',topic:'文档版本与交付包',members:['sam','morgan','chen','echo'],unread:0},
 ...['chen','ada','cy','iris'].map(chKey=>({id:'dm-'+chKey,name:chKey==='chen'?'Chen':PEOPLE[chKey].n,project:'p1',topic:'项目内私信 · 消息不直接改变工作项状态',members:['sam',chKey],dm:chKey,unread:chKey==='ada'?1:0})),
 {id:'agent-direct',name:'Atlas ↔ Ada',project:'p1',topic:'Agent 之间的私信，仅可查看',members:['lead','ada'],readonly:true,unread:0},
 {id:'exec-tax',name:'税额修复 · Ada',project:'p1',topic:'BIL-139 · 分支 #3 · studio-mini · 等待工具权限',members:['chen','ada'],exec:true,unread:1}
];
function chEsc(chValue){return String(chValue??'').replace(/[&<>"']/g,chChar=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[chChar]));}
function chRoom(){return chRooms.find(chR=>chR.id===chState.id)||chRooms[1];}
function chBtn(chText,chAction,chClass='',chDisabled=false,chReason=''){return `<button type="button" class="btn ${chClass}" onclick="${chAction}" ${chDisabled?'disabled':''} ${chReason?`title="${chEsc(chReason)}"`:''}>${chText}</button>`;}
function chName(chKey){return chKey==='chen'?'Chen':PEOPLE[chKey].n;}
function chStatus(chKey){return chKey==='cy'?'离线':PEOPLE[chKey].k==='a'?'运行中':'在线';}
function chPerson(chKey){return `<span class="row wrap"><span class="ch-avatar">${chEsc(chName(chKey).slice(0,2))}</span><b>${chEsc(chName(chKey))}</b><span class="chip">${PEOPLE[chKey].k==='a'?'Agent':'人'}</span><span class="small muted">${chStatus(chKey)}</span></span>`;}
function chSet(chKey,chValue){chState[chKey]=chValue;if(chKey==='actor'){chState.thread=null;if(chState.id==='agent-direct'&&chValue!=='sam')chState.id='billing';}chRender();}
function chRender(){const chRoot=document.getElementById('ch-root');if(chRoot){chRoot.outerHTML=chPage();chSearch(chState.search);chUpdateSend();if(typeof icons==='function')icons();}}
function chOpen(chId){chState.pane='middle';chState.thread=null;go('chat/'+chId);if(chState.id===chId)chRender();}
function chThread(chId){chState.thread=chId;chState.right=true;chState.pane='right';chRender();}
function chNav(chR){return `<a class="ch-item ${chR.id===chState.id?'ch-active':''}" href="#/chat/${chR.id}" onclick="chState.pane='middle';chState.thread=null" data-ch-name="${chEsc(chR.name.toLowerCase())}"><span class="grow" style="font-weight:${chR.unread?700:400}">${chEsc(chR.name)}</span>${chR.mention?'<span class="badge b-primary">@</span>':''}${chR.unread?`<span class="badge b-info">${chR.unread}</span>`:''}${chR.dm?`<span class="ch-dot" style="background:var(--${chStatus(chR.dm)==='离线'?'muted-fg':chStatus(chR.dm)==='在线'?'ok':'primary'})" title="${chStatus(chR.dm)}"></span><span class="xs muted">${chStatus(chR.dm)}</span>`:''}</a>`;}
function chLeft(){return `<aside class="ch-left" aria-label="会话列表"><div class="row wrap"><b class="grow">${chEsc(TEAM.name)}</b>${chBtn('新建','chNew()','sm')}</div><label class="stack small">搜索会话<input aria-label="搜索会话" value="${chEsc(chState.search)}" oninput="chSearch(this.value)" placeholder="频道、私信或执行"></label><section><h3>提及与线程</h3>${chNav(chRooms[0])}</section><section><h3>频道</h3><div class="muted small">账单中心 · 默认频道置顶</div>${chRooms.filter(chR=>['billing','billing-review'].includes(chR.id)).map(chNav).join('')}<div class="muted small">文档站</div>${chNav(chRooms.find(chR=>chR.id==='docs'))}${chRooms.filter(chR=>chR.custom).map(chNav).join('')}</section><section><h3>私信</h3><div class="muted xs">人</div>${chNav(chRooms.find(chR=>chR.id==='dm-chen'))}<div class="muted xs">Agent</div>${chRooms.filter(chR=>chR.dm&&chR.dm!=='chen').map(chNav).join('')}${chState.actor==='sam'?`<details><summary>Agent 私信（只读）</summary><p class="muted xs">仅所有者可见 · 同项目</p>${chNav(chRooms.find(chR=>chR.readonly))}</details>`:''}</section><section><h3>执行会话</h3>${chNav(chRooms.find(chR=>chR.exec))}<div class="small muted">BIL-139 · ${chState.permission?'请求已处理':'1 个权限请求待你回应'}</div></section><div class="sep"></div><label class="stack small">身份预览<select onchange="chSet('actor',this.value)">${[['sam','你 · 所有者'],['morgan','你 · 交付负责人'],['ada','你 · Agent']].map(([chId,chText])=>`<option value="${chId}" ${chState.actor===chId?'selected':''}>${chText}</option>`).join('')}</select></label><p class="muted xs">浏览器内存演示 · 刷新恢复样例</p></aside>`;}
const chParent={intro:{who:'morgan',time:'08:58',text:'@Atlas BIL-144 文档交给谁合适？今天想把 CSV 导出一起交付。'},done:{who:'ada',time:'09:20',text:'已声明完成（未验证）：BIL-142，提交 CSV 导出产物、证据与未验证范围。'},dm:{who:'ada',time:'09:24',text:'你可以在这里澄清需求。工作请求会生成派单提案，不会直接执行。'}};
function chMessage(chId,chM,chReply=true){return `<article class="ch-message"><div class="ch-avatar">${chEsc(chName(chM.who).slice(0,2))}</div><div class="grow"><div class="row wrap"><b>${chEsc(chName(chM.who))}</b><span class="chip">${PEOPLE[chM.who].k==='a'?'Agent':'人'}</span><time class="muted xs">${chEsc(chM.time)}</time></div><div class="bubble" style="white-space:pre-wrap;overflow-wrap:anywhere">${chEsc(chM.text)}</div>${chReply?chBtn(`${(chState.replies[chId]||[]).length+(chId==='intro'?2:0)} 条回复 → 打开线程`,`chThread('${chId}')`,'ghost sm'):''}</div></article>`;}
function chDispatch(){return `<div class="decision-card"><div class="row wrap">${I('split')}<b>主管 Agent Atlas · 派单提案</b><span class="badge b-primary">${chState.dispatch?chEsc(chState.dispatch):'待批准'}</span></div><dl class="kv"><dt>工作项</dt><dd>BIL-144 · CSV 导出接口文档</dd><dt>推荐</dt><dd>Bo · 82.6 分 · Ada 72.7 分（满载）</dd><dt>理由</dt><dd>文档技能匹配，近 90 天首次验收率 0.81</dd><dt>护栏</dt><dd>就绪闸门已满足 · 低风险 · 人类负责人 Morgan；执行槽以派发时预检为准</dd></dl><div class="row wrap">${chBtn('批准',"chDispatchAction(false)",'primary sm',!!chState.dispatch||chState.actor==='ada'||chState.preview==='offline')}${chBtn('改派',"chDispatchAction(true)",'sm',!!chState.dispatch||chState.actor==='ada'||chState.preview==='offline')}</div><p class="muted xs">${chState.actor==='ada'?'你没有工作项指派权限；主管不能批准自己派出的计划。':'批准后才产生指派裁决；聊天内容不是业务状态真相源。'}</p></div>`;}
function chCards(){const chOff=chState.preview==='offline',chAgent=chState.actor==='ada';return `<div class="stack"><div class="decision-card"><b>完成声明 · BIL-142</b><p>${chEsc(WI.find(chW=>chW.id==='BIL-142').t)}</p><div class="row wrap">${ladder(2)}<span class="badge b-ok">L2 · 内部验收通过</span></div><dl class="kv"><dt>L1</dt><dd>已声明完成（未验证）</dd><dt>L2</dt><dd>平台重跑 + 测试 Agent + 产品验收 Agent 全部通过</dd><dt>L3 / L4</dt><dd>团队待裁决 / 甲方未验收</dd><dt>验证 / 覆盖</dt><dd>4/4 · 验收标准 3/3 · 证据 5 条</dd><dt>未验证范围</dt><dd>生产数据与外部服务</dd></dl>${chBtn('去评审',"go('review')",'sm primary')}</div><div class="decision-card"><b>裁决 · BIL-142</b><p class="small">基线 R-12 v3 有效 · 无他人认领 · 人类负责人 Morgan</p><p class="small muted">${chAgent?'你是执行 Agent，职责分离禁止自审；Agent 不能执行接受流转。':'你以团队所有者 / 交付负责人角色裁决。'}</p>${chState.decision?`<div class="note ok">${chEsc(chState.decision)} · 本地演示结果</div>`:`<div class="row wrap">${chBtn('通过',"chDecision('通过')",'primary sm',chAgent||chOff)}${chBtn('要求修改',"chDecision('要求修改')",'sm',chAgent||chOff)}${chBtn('拒绝',"chDecision('拒绝')",'danger sm',chAgent||chOff)}</div><p class="small muted">拒绝会进入从头重做分支；需重新认证。要求修改需结构化反馈。</p>`}</div><div class="decision-card" style="border-color:var(--danger)"><div class="row">${I('octagon-alert')}<b style="color:var(--danger)">停线 · 导出链路</b></div><dl class="kv"><dt>原因</dt><dd>检测到冻结验收测试被修改</dd><dt>影响</dt><dd>该样例停线事件暂停导出链路与下游交付，已通知负责人</dd><dt>处置</dt><dd>只允许负责人确认处置后恢复</dd></dl>${chBtn('查看',"chStopDetails()",'danger sm')}</div>${chDispatch()}</div>`;}
function chPermission(){const chDisabled=!!chState.permission||chState.actor==='ada'||chState.preview==='offline';return `<div class="decision-card"><div class="row wrap">${I('shield-alert')}<b>权限请求 · 等待你决定</b><span id="ch-countdown" class="badge b-warn"></span></div><dl class="kv"><dt>工具</dt><dd>Edit · Claude Code</dd><dt>命令</dt><dd class="mono">逐行计算 roundHalfUp，再汇总税额</dd><dt>影响路径</dt><dd class="mono">/work/billing/src/billing/tax.ts</dd><dt>修改范围</dt><dd>税额舍入逻辑；不允许修改冻结验收测试</dd><dt>请求状态</dt><dd>${chState.permission?chEsc(chState.permission):'需要确认 · 演示最后 15 秒（正式请求 30 分钟）'}</dd></dl><div class="row wrap">${chBtn('允许一次',"chPermit('已提交 · 允许一次')",'primary sm',chDisabled)}${chBtn('拒绝',"chPermit('已提交 · 拒绝')",'sm',chDisabled)}</div><p class="muted xs">${chState.actor==='ada'?'仅有权限的人可以决定，Agent 不可批准工具权限。':chState.permission?'请求已处理，不能重复决定。':'拒绝后本次工具不会执行；决定不代表已送达运行时。'}</p></div>`;}
function chFlow(){const chR=chRoom();if(chState.preview==='empty')return '<div class="empty"><b>空会话</b><p>还没有消息。你可以发送第一条消息。</p></div>';if(chR.exec)return `<div class="note info">执行正在运行 · BIL-139 · 分支 #3 · 等待你决定</div>${chMessage('exec-start',{who:'chen',time:'09:12',text:'按反馈改为逐行舍入，并补充负数退款测试。'})}<details><summary>读取 tax.ts · 另 4 条执行事件</summary><p class="mono small">09:12 定位 roundHalfUp · 4 处<br>09:12 读取反馈 F2<br>09:13 检查冻结验收测试（只读）<br>09:13 生成逐行舍入方案</p></details>${chPermission()}`;if(chR.readonly)return `<div class="note info">Agent 之间的私信，仅可查看；私信不产生派单或状态变更。</div>${chMessage('agent-msg',{who:'lead',time:'09:10',text:'请确认文档引用 R-12 v3。此处只交流，不产生工作项分派。'})}${chMessage('agent-reply',{who:'ada',time:'09:11',text:'已读取需求基线；等待有权限的人批准派单。'})}`;if(chR.dm)return chMessage('dm',{...chParent.dm,who:chR.dm,text:chR.dm==='chen'?'我已核对 CSV 列顺序，证据在 BIL-142。':chParent.dm.text});if(chR.id==='docs')return chMessage('docs-msg',{who:'echo',time:'09:06',text:'已声明完成（未验证）：文档产物已提交，等待独立验证与裁决。'});return `${chMessage('intro',chParent.intro)}<details><summary>执行事件 · 产物采集完毕 · 另 4 条执行事件</summary><p class="muted small">09:14 隔离环境准备<br>09:15 构建结束<br>09:16 产物指纹锁定<br>09:17 证据采集结束</p></details>${chMessage('done',chParent.done)}${chCards()}`;}
function chComposer(){const chR=chRoom();if(chR.readonly)return '<div class="note info">你只能查看：人类不能向 Agent 间私信发送消息。</div>';return `<div class="ch-compose"><label class="stack small">消息<textarea id="ch-input" rows="3" maxlength="8001" oninput="chInput(this)" onkeydown="chKey(event)" placeholder="发消息，@ 提及成员，/ 打开命令">${chEsc(chState.drafts[chState.id]||'')}</textarea></label><div id="ch-candidates" class="stack" hidden></div><div class="row wrap"><span id="ch-send-reason" class="muted xs grow"></span>${chBtn('发送','chSend()','primary sm',true)}</div>${chR.dm&&PEOPLE[chR.dm].k==='a'?'<p class="note info">将生成派单提案，由有权限的人批准</p>':'<p class="muted xs">消息不直接派单或改变工作项状态；不支持 @all / @channel。</p>'}${chR.exec?'<p class="muted xs">执行运行中，暂不能发起新一轮；请先回应权限请求。</p>':''}</div>`;}
function chRight(){const chR=chRoom();return `<aside class="ch-right" aria-label="线程或会话详情"><div class="row"><button class="btn ghost sm ch-back" onclick="chSet('pane','middle')">返回会话</button><h3 class="grow">${chState.thread?'线程':'会话详情'}</h3>${chBtn('关闭',"chState.right=false;chState.pane='middle';chRender()",'ghost sm')}</div>${chState.thread?chThreadBody():`<section><h3>成员 · ${chR.members.length}</h3>${['h','a'].map(chKind=>`<p class="muted small">${chKind==='h'?'人':'Agent'}</p>${chR.members.filter(chK=>PEOPLE[chK].k===chKind).map(chK=>`<div class="stack" style="padding:8px 0;align-items:flex-start">${chPerson(chK)}${chKind==='a'?`<span class="origin ${PEOPLE[chK].origin?'s':'h'}">${PEOPLE[chK].origin?'AI 创建':'人工创建'}</span>`:''}</div>`).join('')}`).join('')}</section><section><h3>置顶</h3><a href="#/requirements">需求 R-12 v3 · CSV 导出</a><br><a href="#/workitem/BIL-142">工作项 BIL-142</a></section><section><h3>文件</h3>${chBtn('导出验证报告 · 4/4',"chFile()",'ghost sm')}<p class="muted xs">产物 test-report.json · 证据指纹已锁定</p></section><section><h3>会话设置</h3><dl class="kv"><dt>项目</dt><dd>${chR.project==='p3'?'文档站':'账单中心'}</dd><dt>保留</dt><dd>消息不物理删除</dd><dt>通知</dt><dd>仅提及与线程</dd></dl>${chBtn('通知设置','chSettings()','sm')}<p class="muted xs">${chR.id==='billing'||chR.readonly?'默认频道与私信频道不能归档。':'项目关闭或取消后频道归档只读。'}</p></section>`}</aside>`;}
function chThreadBody(){const chId=chState.thread,chM=chParent[chId]||{who:'chen',time:'09:12',text:'税额修复执行 · 事件与证据讨论'};return `<section>${chMessage(chId,chM,false)}</section><section><h3>回复</h3>${chId==='intro'?chMessage('reply-example',{who:'lead',time:'09:00',text:'推荐 Bo；已经生成待批准提案。'},false)+chMessage('reply-human',{who:'morgan',time:'09:01',text:'我会先核对工作项与执行槽。'},false):'<p class="muted small">围绕父消息交流，回复不替代裁决。</p>'}${(chState.replies[chId]||[]).map(chM=>chMessage('reply-local',chM,false)).join('')}</section><section><label class="stack">回复<textarea id="ch-reply" rows="3" maxlength="8000" oninput="chState.drafts['thread-'+chState.id+'-'+chState.thread]=this.value">${chEsc(chState.drafts['thread-'+chState.id+'-'+chId]||'')}</textarea></label>${chBtn('发送回复','chReply()','primary sm',chRoom().readonly||chState.preview==='offline')}${chRoom().readonly?'<p class="muted xs">Agent 间私信只读。</p>':''}</section>`;}
function chPage(){const chR=chRoom();return `<div id="ch-root" class="ch-root ${chState.right?'':'ch-no-right'} ch-pane-${chState.pane}">${chLeft()}<main class="ch-middle" aria-label="会话消息"><header class="ch-head"><div class="row wrap"><button class="btn ghost sm ch-back" onclick="chSet('pane','left')">返回列表</button><h2 class="grow">${chEsc(chR.name)}</h2>${chBtn('详情',"chState.right=!chState.right;chState.thread=null;chState.pane='right';chRender()",'sm')}</div><p class="small muted">${chEsc(chR.topic)} · ${chR.members.length} 位成员 · ${chR.project==='p3'?'文档站':'账单中心'}</p><div class="row wrap small"><span>状态预览</span>${[['normal','正常'],['offline','断线重连中'],['empty','空会话']].map(([chV,chT])=>`<button class="chip ${chState.preview===chV?'on':''}" aria-pressed="${chState.preview===chV}" onclick="chSet('preview','${chV}')">${chT}</button>`).join('')}</div>${chState.preview==='offline'?'<div class="note warn" role="status">正在重新连接… · 写操作暂停，草稿保留</div>':''}</header><div class="ch-flow" id="ch-flow">${chFlow()}${(chState.messages[chState.id]||[]).map((chM,chN)=>chMessage('local-'+chState.id+'-'+chN,chM)).join('')}</div>${chComposer()}</main>${chState.right?chRight():''}</div>`;}
function chSearch(chValue){chState.search=chValue;document.querySelectorAll('#ch-root [data-ch-name]').forEach(chEl=>{chEl.hidden=!chEl.dataset.chName.includes(chValue.toLowerCase());});}
function chInput(chEl){chState.drafts[chState.id]=chEl.value;const chBox=document.getElementById('ch-candidates'),chToken=chEl.value.slice(0,chEl.selectionStart).match(/(?:^|\s)([@/][^\s]*)$/);chBox.hidden=!chToken;chBox.innerHTML='';if(chToken){const chT=chToken[1],chQuery=chT.slice(1).toLowerCase();if(chT[0]==='@')chBox.innerHTML=['h','a'].map(chKind=>`<div class="muted small">${chKind==='h'?'人':'Agent'}</div>${chRoom().members.filter(chK=>PEOPLE[chK].k===chKind&&chName(chK).toLowerCase().includes(chQuery)).map(chK=>chBtn(`${chEsc(chName(chK))} · ${chStatus(chK)}`,`chInsert('@${chName(chK)} ')`,'ghost sm')).join('')}`).join('');else chBox.innerHTML=['派单','停线','新建工作项','搜索知识'].filter(chT=>chT.includes(chQuery)).map(chT=>chBtn('/'+chT,`chInsert('/${chT} ')`,'ghost sm')).join('');}chUpdateSend();}
function chInsert(chText){const chEl=document.getElementById('ch-input'),chBefore=chEl.value.slice(0,chEl.selectionStart),chAfter=chEl.value.slice(chEl.selectionEnd);chEl.value=chBefore.replace(/[@/][^\s]*$/,chText)+chAfter;chEl.focus();chInput(chEl);}
function chUpdateSend(){const chEl=document.getElementById('ch-input');if(!chEl)return;const chReason=chState.preview==='offline'?'断线重连中，暂不能发送':chRoom().exec?'执行运行中，不能发起新一轮':chEl.value.length>8000?'消息最多 8000 字符':!chEl.value.trim()?'请输入消息':'';const chB=document.querySelector('.ch-compose button.primary');chB.disabled=!!chReason;document.getElementById('ch-send-reason').textContent=chReason;}
function chKey(chEvent){if(chEvent.key==='Escape'){document.getElementById('ch-candidates').hidden=true;return;}if(chEvent.key==='Enter'&&!chEvent.shiftKey&&!chEvent.isComposing){chEvent.preventDefault();chSend();}}
function chSend(){const chText=(chState.drafts[chState.id]||'').trim();if(!chText||chText.length>8000||chState.preview==='offline'||chRoom().readonly||chRoom().exec)return;const chMentions=chText.match(/@[^\s]+/g)||[];if(chMentions.length>20||chMentions.some(chT=>!chRoom().members.some(chK=>'@'+chName(chK)===chT)))return toast('每条最多 20 个提及；只能提及本会话成员，不支持 @all / @channel');if(chText.startsWith('/')){if(chText.startsWith('/派单'))return chDispatchAction(false);if(chText.startsWith('/停线'))return chStopDetails();if(chText.startsWith('/新建工作项'))return go('work');if(chText.startsWith('/搜索知识'))return go('knowledge');}(chState.messages[chState.id]||=[]).push({who:chState.actor,time:'刚刚',text:chText});chState.drafts[chState.id]='';if(chRoom().dm&&PEOPLE[chRoom().dm].k==='a'&&/请.*做/.test(chText)){(chState.messages[chState.id]).push({who:'lead',time:'刚刚',text:'已生成派单提案草稿：'+chText+'。由有权限的人核对工作项、就绪闸门与候选后批准。'});toast('派单提案草稿已生成，未执行任务');}chRender();}
function chReply(){if(chRoom().readonly||chState.preview==='offline')return;const chEl=document.getElementById('ch-reply');if(!chEl.value.trim())return toast('请填写回复');(chState.replies[chState.thread]||=[]).push({who:chState.actor,time:'刚刚',text:chEl.value.trim()});delete chState.drafts['thread-'+chState.id+'-'+chState.thread];chRender();}
function chModal(chTitle,chBody,chFooter){openModal(`<div class="stack" style="padding:24px"><h3>${chTitle}</h3>${chBody}<div class="row wrap">${chBtn('取消','closeModal()','ghost')}${chFooter}</div></div>`);}
function chDecision(chAction){if(chState.actor==='ada'||chState.preview==='offline'||chState.decision)return;chModal(chAction+' · BIL-142',chAction==='通过'?'<p>验证 4/4、内部验收通过、基线有效。通过后进入团队已接受，不代表甲方已验收。</p>':`<label class="stack">失败类别<select id="ch-category"><option>质量拒绝</option><option>策略变更</option></select></label><label class="stack">反馈类别<select><option>功能缺陷</option><option>需求偏差</option><option>样式</option><option>性能</option><option>安全</option><option>其他</option></select></label><label class="stack">位置<input id="ch-location" placeholder="文件路径或界面"></label><label class="stack">期望<input id="ch-expected"></label><label class="stack">详情（至少 5 字）<textarea id="ch-feedback" oninput="chValidateFeedback()"></textarea></label><label class="stack">理由（必填）<textarea id="ch-reason" oninput="chValidateFeedback()"></textarea></label><p class="note ${chAction==='拒绝'?'danger':'warn'}">${chAction==='拒绝'?'从头重做；原证据保留。需重新认证。':'在原产出上修改；返回返工分支。'}</p>`,chBtn(chAction==='拒绝'?'重新认证并拒绝（演示）':'确认'+chAction,`chSaveDecision('${chAction}')`,chAction==='拒绝'?'danger':'primary',chAction!=='通过'));}
function chValidateFeedback(){document.querySelector('#modal button.primary,#modal button.danger').disabled=document.getElementById('ch-feedback').value.trim().length<5||!document.getElementById('ch-reason').value.trim();}
function chSaveDecision(chAction){if(chState.actor==='ada'||chState.preview==='offline')return;if(chAction!=='通过'&&(document.getElementById('ch-feedback').value.trim().length<5||!document.getElementById('ch-reason').value.trim()))return;chState.decision=chAction;closeModal();chRender();toast('本地裁决演示已记录；未写入业务对象');}
function chDispatchAction(chReassign){if(chState.actor==='ada'||chState.preview==='offline'||chState.dispatch)return;chModal(chReassign?'改派提案':'批准派单提案',`<p>BIL-144 · 人类负责人 Morgan · 低风险 · 就绪闸门满足</p><label class="stack">执行者<select id="ch-assignee"><option value="bo">Bo · 文档技能匹配</option><option value="echo">Echo · AI 创建 · 执行者</option></select></label><label class="stack">${chReassign?'改派理由（必填）':'派单理由'}<textarea id="ch-dispatch-reason" oninput="document.querySelector('#modal button.primary').disabled=${chReassign?'!this.value.trim()':'false'}">${chReassign?'':'文档技能匹配，等待机器槽位'}</textarea></label><p class="small muted">需工作项指派权限；处理时重新检查版本、候选资格和执行槽。</p>`,chBtn('确认',`chSaveDispatch(${chReassign})`,'primary',chReassign));}
function chSaveDispatch(chReassign){if(chState.actor==='ada'||chState.preview==='offline')return;if(chReassign&&!document.getElementById('ch-dispatch-reason').value.trim())return;chState.dispatch='已批准 → '+chName(document.getElementById('ch-assignee').value);closeModal();chRender();toast('本地派单演示；未创建真实分派');}
function chPermit(chResult){if(chState.permission||chState.actor==='ada'||chState.preview==='offline')return;if(Date.now()>=chState.deadline){chState.permission='已过期';chRender();return;}chState.permission=chResult;chRender();toast('本地决定已提交，运行时送达尚未模拟');}
function chStopDetails(){chModal('停线处置',`<div class="note danger">冻结验收测试被修改；导出链路与下游交付暂停。恢复前须由负责人确认处置，需重新认证。</div><p>保留原产物与审计证据，恢复冻结测试后重新验证。</p><p class="muted small">本页只读展示停线，处置需前往工作项。</p>`,chBtn('查看工作项',"closeModal();go('workitem/BIL-142')",'danger'));}
function chFile(){chModal('验证报告','<pre class="code">必需验证：4/4 通过\n验收标准：3/3 覆盖\n局限：不包含生产数据与外部服务\n内部验收：测试 Agent 与产品验收 Agent 均通过</pre>',chBtn('查看执行',"closeModal();go('executions')",'primary'));}
function chSettings(){chModal('会话通知设置','<label class="stack">通知范围<select id="ch-notify"><option>仅提及与线程</option><option>全部消息</option><option>静音</option></select></label><p class="muted small">仅本地演示，权限请求与停线告警不会被静音。</p>',chBtn('保存',"closeModal();toast('通知偏好已保存于演示，告警不受影响')",'primary'));}
function chNew(){chModal('新建频道','<label class="stack">频道名（1–80 字）<input id="ch-new-name" maxlength="80" oninput="document.querySelector(\'#modal button.primary\').disabled=!this.value.trim()"></label><p class="small muted">项目：账单中心 · 自建频道 · 成员：你、Chen、Ada</p>',chBtn('创建','chCreate()','primary',true));}
function chCreate(){const chNameValue=document.getElementById('ch-new-name').value.trim();if(!chNameValue)return;if(chRooms.some(chR=>chR.name==='# '+chNameValue))return toast('频道名已存在');const chId='custom-'+chRooms.length;chRooms.push({id:chId,name:'# '+chNameValue,topic:'项目自建频道',project:'p1',members:[chState.actor,'chen','ada'].filter((chK,chN,chA)=>chA.indexOf(chK)===chN),unread:0,custom:true});closeModal();chState.preview='empty';chOpen(chId);}
if(!document.getElementById('ch-style'))document.head.insertAdjacentHTML('beforeend',`<style id="ch-style">
.ch-root{height:calc(100vh - 57px);display:grid;grid-template-columns:260px minmax(0,1fr) 320px;background:var(--bg);color:var(--fg);overflow:hidden}.ch-root.ch-no-right{grid-template-columns:260px minmax(0,1fr)}.ch-left,.ch-right{overflow:auto;min-height:0;padding:20px;display:flex;flex-direction:column;gap:20px;background:var(--card)}.ch-left{border-right:1px solid var(--border)}.ch-right{border-left:1px solid var(--border)}.ch-middle{min-width:0;min-height:0;display:flex;flex-direction:column}.ch-head{padding:16px 24px;border-bottom:1px solid var(--border);background:var(--card)}.ch-head h2{font-size:20px;margin:0}.ch-head p{margin:8px 0}.ch-flow{overflow:auto;min-height:0;flex:1;padding:24px;display:flex;flex-direction:column;gap:20px}.ch-compose{padding:16px 24px;border-top:1px solid var(--border);background:var(--card)}.ch-compose textarea,.ch-right textarea,.ch-left input,.ch-left select{width:100%;background:var(--bg);color:var(--fg);border:1px solid var(--border);padding:10px;font:inherit;border-radius:6px}.ch-item{display:flex;align-items:center;gap:8px;padding:10px 8px;border-radius:6px;color:var(--fg);text-decoration:none;min-height:44px}.ch-item[hidden]{display:none}.ch-active{background:var(--primary-soft);color:var(--primary)}.ch-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0}.ch-avatar{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;flex-shrink:0;border-radius:8px;background:var(--primary-soft);color:var(--primary);font-weight:700}.ch-message{display:flex;gap:12px}.ch-message .bubble{margin:8px 0}.ch-root section h3{font-size:14px;margin:0 0 12px}.ch-root summary{cursor:pointer;min-height:44px;padding:10px 0;color:var(--muted-fg)}.ch-back{display:none}.ch-root button:focus-visible,.ch-root a:focus-visible,.ch-root input:focus-visible,.ch-root textarea:focus-visible{outline:2px solid var(--primary);outline-offset:2px}.ch-root #ch-candidates{max-height:180px;overflow:auto;border:1px solid var(--border);padding:8px;background:var(--card)}.ch-root #ch-candidates[hidden]{display:none}.ch-root .decision-card{margin:0}.ch-root .kv dd{overflow-wrap:anywhere}
@media(max-width:859px){.ch-root,.ch-root.ch-no-right{grid-template-columns:minmax(0,1fr)}.ch-left,.ch-middle,.ch-right{display:none}.ch-pane-left .ch-left{display:flex}.ch-pane-middle .ch-middle{display:flex}.ch-pane-right .ch-right{display:flex}.ch-back{display:inline-flex}.ch-root .btn,.ch-root .chip{min-height:44px}.ch-head,.ch-compose{padding:12px}.ch-flow{padding:16px}.ch-right{border:0}.ch-root .kv{grid-template-columns:90px minmax(0,1fr)}}
</style>`);
PAGES.chat=(chArg)=>{let chId;try{chId=decodeURIComponent(chArg||'billing');}catch{chId='billing';}const chR=chRooms.find(chR=>chR.id===chId||chR.name.replace(/^#\s*/,'')===chId);chState.id=chR?chR.id:'billing';if(chRoom().readonly&&chState.actor!=='sam')return '<div class="empty">仅所有者可查看 Agent 私信。<a href="#/chat/billing">返回账单中心</a></div>';if(chState.id==='exec-tax'&&!chState.deadline)chState.deadline=Date.now()+15000;setTimeout(()=>{chSearch(chState.search);chUpdateSend();},0);return chPage();};
TITLES.chat='会话';NAVPARENT.chat='chat';
PAGES.channels=()=>{setTimeout(()=>go('chat'),0);return '';};
const chTimer=setInterval(()=>{if(!document.getElementById('ch-root'))return;const chCountdown=document.getElementById('ch-countdown');if(chCountdown){const chSeconds=Math.max(0,Math.ceil((chState.deadline-Date.now())/1000));chCountdown.textContent=chState.permission?'请求已处理':`剩余 ${chSeconds} 秒 · 倒计时示意`;if(chSeconds===0&&!chState.permission){chState.permission='已过期 · 未作出决定';chRender();}}chUpdateSend();},1000);
